import{_ as a,o as t,c as n,a2 as s}from"./chunks/framework.DncwoWA8.js";const i="/projects/ai-skills/diagrams/debloat-a-project.svg",m=JSON.parse('{"title":"Debloat a project","description":"","frontmatter":{"title":"Debloat a project"},"headers":[],"relativePath":"workflows/debloat-a-project.md","filePath":"workflows/debloat-a-project.md"}'),r={name:"workflows/debloat-a-project.md"};function o(p,e,c,l,d,h){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="debloat-a-project" tabindex="-1">Debloat a project <a class="header-anchor" href="#debloat-a-project" aria-label="Permalink to &quot;Debloat a project&quot;">​</a></h1><p>Reduce unnecessary complexity in existing code, configuration, dependencies, or abstractions without removing required behavior.</p><p>Start with a bounded area that seems harder to understand or maintain than its requirements justify. Finish with evidence-backed decisions and, when authorized, verified reductions. Keeping the current design is a valid outcome.</p><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><p><img src="'+i+`" alt="Evidence-backed keep, simplify, or defer decisions and behavior-preserving reductions."></p><p><a href="/projects/ai-skills/diagrams/debloat-a-project.html" class="vp-raw">Open interactive diagram</a> · <a href="/projects/ai-skills/diagrams/debloat-a-project.svg">Download SVG</a> · <a href="/projects/ai-skills/diagram-sources/debloat-a-project.json">Editable source</a></p><p>The diagram shows suggested handoffs, not automatic execution or new instruction dependencies. Select a node in the interactive diagram for its source references.</p><details><summary>Read the flow as text</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>/debloat: inspect requirements</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Trace consumers, costs, and risks</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Decide: keep / simplify / defer</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Agree a bounded reduction</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Establish behavior checks</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>/coding-with-rules: simplify</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Verify → review if selected</span></span>
<span class="line"><span>    ├─ changed behavior → reassess</span></span>
<span class="line"><span>    └─ broad redesign → planning</span></span></code></pre></div></details><p>The investigation selects justified changes. The implementation branch is conditional on approval, not an automatic consequence of finding a candidate.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Use <a href="/projects/ai-skills/skills/debloat.html"><code>debloat</code></a> in simplify mode for an existing project. Its prevent mode can instead challenge a proposed design before implementation.</p><p>Confirm the allowed area, required behavior, public contracts, compatibility obligations, and edit authority. Read the <a href="/projects/ai-skills/workflows/supporting-tools.html#before-you-start">execution safeguards</a>. An inventory or review request stays read-only.</p><p>Do not define success as a line, file, or package deletion quota. The goal is lower total comprehension, maintenance, testing, security, and operating cost.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><h3 id="_1-investigate-each-candidate" tabindex="-1">1. Investigate each candidate <a class="header-anchor" href="#_1-investigate-each-candidate" aria-label="Permalink to &quot;1. Investigate each candidate&quot;">​</a></h3><p>Read its implementation, tests, configuration, manifests, and contracts. Trace actual consumers, including exports, plugins, CLIs, generated code, build or deployment wiring, and integrations where relevant.</p><p>For each candidate, record its requirement, consumers, present cost, a concrete simpler alternative, risks, and unknowns. An import search alone cannot prove a mechanism is unused.</p><p>Investigate pass-through layers, speculative extension points, duplicated facts, flags, dependencies, and optimizations. Do not treat any of those categories as automatic deletion orders.</p><h3 id="_2-choose-keep-simplify-or-defer" tabindex="-1">2. Choose keep, simplify, or defer <a class="header-anchor" href="#_2-choose-keep-simplify-or-defer" aria-label="Permalink to &quot;2. Choose keep, simplify, or defer&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Decision</th><th>Evidence to record</th></tr></thead><tbody><tr><td>Keep</td><td>The requirement, boundary, measured constraint, or lower total cost that justifies the current mechanism</td></tr><tr><td>Simplify</td><td>The concrete alternative and how it preserves required behavior and consumers</td></tr><tr><td>Defer</td><td>The unknown consumer, compatibility risk, missing evidence, or absent authority blocking a safe decision</td></tr></tbody></table><p>Retain justified authorization, established cryptography, error handling, observability, recovery, and necessary tests. Replacing a maintained library with custom code can increase obligations even if it removes a dependency.</p><p>Compare the total change, including work shifted to callers. Fewer lines alone are not evidence of a better design.</p><h3 id="_3-bound-the-approved-change" tabindex="-1">3. Bound the approved change <a class="header-anchor" href="#_3-bound-the-approved-change" aria-label="Permalink to &quot;3. Bound the approved change&quot;">​</a></h3><p>Present the proposed reductions and their risks before editing. Keep unrelated cleanup out of the change.</p><p>A small, clear reduction can go directly to implementation. For a wide restructuring or unsettled contract, return to <a href="/projects/ai-skills/workflows/plan-a-project.html">planning</a> to agree behavior and divide the work. Use compatibility-preserving sequencing when required.</p><p>If the current design remains the simpler sound choice, stop with the keep decision.</p><h3 id="_4-preserve-behavior-while-simplifying" tabindex="-1">4. Preserve behavior while simplifying <a class="header-anchor" href="#_4-preserve-behavior-while-simplifying" aria-label="Permalink to &quot;4. Preserve behavior while simplifying&quot;">​</a></h3><p>Use <a href="/projects/ai-skills/skills/coding-with-rules.html"><code>coding-with-rules</code></a> for source changes. Establish focused behavioral coverage before collapsing or removing a mechanism. Use contract or integration checks across important boundaries.</p><p>Preserve public behavior, defaults, errors, side effects, and compatibility unless their change is explicitly approved. Make small, reviewable reductions, recheck consumers after rewiring, and remove only newly unnecessary mechanisms within scope.</p><p>If meaningful coverage is infeasible, report that limitation before relying on weaker checks. Do not delete or weaken tests to make the new design pass.</p><h3 id="_5-verify-the-reduction" tabindex="-1">5. Verify the reduction <a class="header-anchor" href="#_5-verify-the-reduction" aria-label="Permalink to &quot;5. Verify the reduction&quot;">​</a></h3><p>Run the applicable project checks, inspect the full diff, and use <a href="/projects/ai-skills/workflows/supporting-tools.html#review-an-existing-change">independent review</a> when requested and supported.</p><p>Update affected documentation when configuration, public interfaces, or reader tasks change. For an internal-only reduction, give a concrete no-documentation-change reason.</p><p>Stop and reassess if a necessary boundary disappears or an unapproved behavior change appears.</p><h2 id="example-investigate-an-export-factory" tabindex="-1">Example: investigate an export factory <a class="header-anchor" href="#example-investigate-an-export-factory" aria-label="Permalink to &quot;Example: investigate an export factory&quot;">​</a></h2><p>This is an illustrative candidate in the reporting project, not an observed problem in this collection.</p><p>An export factory appears to choose only one CSV exporter. A safe initial request is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>Review the export factory and forwarding layers with /debloat in simplify</span></span>
<span class="line"><span>mode. Stay read-only. Trace public consumers, plugins, configuration, and</span></span>
<span class="line"><span>tests before calling anything unused. Propose keep, simplify, or defer for</span></span>
<span class="line"><span>each candidate. Preserve CSV behavior, permissions, and compatibility.</span></span>
<span class="line"><span>Do not remove dependencies or edit code yet.</span></span></code></pre></div><p>If inspection proves that direct construction preserves every required consumer and contract, the proposal can describe that reduction and its checks. If plugins create exporters through the factory, retain the required boundary or defer until compatibility is understood.</p><p>After the owner approves a specific reduction, implement it with behavior checks. Record both what was removed and which complexity remained justified.</p><h2 id="report-and-stop" tabindex="-1">Report and stop <a class="header-anchor" href="#report-and-stop" aria-label="Permalink to &quot;Report and stop&quot;">​</a></h2><p>Report scope, evidence-backed decisions, actual changes, retained complexity, checks and unrun reasons, uncertainties, and any next approval needed.</p><p>A proposal is not permission to edit. A successful reduction is not permission to continue simplifying unrelated areas, merge, or release.</p><p>For the narrower design-review procedure, see <a href="/projects/ai-skills/workflows/simplify-a-design.html">Remove complexity without removing requirements</a>.</p>`,44)])])}const f=a(r,[["render",o]]);export{m as __pageData,f as default};
